"""Generate standalone offline HTML dashboard (stdlib only); all datasets embedded."""
import json,csv,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
summary=json.loads((ROOT/'results/summary.json').read_text(encoding='utf-8'))
with (ROOT/'results/sensitivity_summary.csv').open(newline='',encoding='utf-8') as f:sens=list(csv.DictReader(f))
all_data=json.dumps({'kpis':summary['scenario_kpis'],'segments':summary['scenario_segments'],'sensitivity':sens},ensure_ascii=False).replace('</','<\\/')
html_page='''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Category Operations | Portfolio Dashboard</title><style>
:root{--navy:#11223f;--blue:#216ce4;--light:#f4f7fc;--ink:#1a2741;--muted:#63728b;--line:#dfe7f0;--teal:#198c7b;--amber:#ae710f}
*{box-sizing:border-box}body{margin:0;background:var(--light);font-family:Inter,ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;color:var(--ink)}.wrap{max-width:1340px;margin:auto;padding:28px 28px 70px}
header{background:linear-gradient(118deg,#11213a,#19427a);color:#fff;padding:32px;border-radius:20px;display:flex;justify-content:space-between;gap:18px;align-items:end}.eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:11px;font-weight:800;color:#abcef9}h1{font-size:32px;margin:9px 0 12px;line-height:1.08}header p{font-size:14px;color:#d2e0f3;max-width:720px;margin:0;line-height:1.5}.pill{display:inline-flex;align-items:center;padding:8px 14px;border:1px solid #83a9dd;border-radius:99px;color:#ebf4ff;font-size:12px;white-space:nowrap}.nav{margin:25px 0;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.nav h2{margin:0;font-size:20px}.nav label{color:var(--muted);font-size:13px;font-weight:700}select{background:white;border:1px solid var(--line);border-radius:10px;padding:10px 14px;color:var(--ink);font-size:13px;min-width:190px}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#fff;border:1px solid var(--line);border-radius:15px;padding:19px;box-shadow:0 5px 18px #11213a06}.metric b{font-size:30px;letter-spacing:-1px;display:block;margin:12px 0 6px}.metric small{font-size:12px;color:var(--muted);font-weight:650}.delta{font-size:12px;color:var(--teal);font-weight:750}.delta.negative{color:var(--amber)}.section{display:grid;grid-template-columns:1.15fr .85fr;gap:16px;margin-top:18px}.card h3{font-size:15px;margin:0 0 15px}.sub{font-size:12px;color:var(--muted);line-height:1.6;margin:-5px 0 14px}.plotrow{margin:11px 0}.plotline{display:flex;justify-content:space-between;font-size:12px;gap:10px;margin-bottom:6px}.track{background:#edf2f8;height:12px;border-radius:99px;overflow:hidden}.fill{height:100%;border-radius:99px;background:linear-gradient(90deg,#3d98ee,#155acb)}.fill.recommend{background:linear-gradient(90deg,#38b5a3,#198c7b)}.rowchips{display:flex;gap:12px;flex-wrap:wrap}.chip{padding:8px 12px;border-radius:9px;background:#f2f7ff;border:1px solid #dfebfb;font-size:12px}.chip strong{display:block;font-size:15px}.callout{border-left:4px solid var(--blue);padding:13px 17px;background:#f2f7ff;border-radius:0 9px 9px 0;margin-top:14px;color:#40506a;font-size:13px;line-height:1.55}.tbl{width:100%;border-collapse:collapse;font-size:12px}.tbl th{text-align:left;background:#f6f9fd;color:#566881;padding:10px;border-bottom:1px solid var(--line);white-space:nowrap}.tbl td{padding:10px;border-bottom:1px solid #edf1f6}.tbl tr:last-child td{border:0}.right{text-align:right}.tag{font-size:11px;border-radius:99px;padding:5px 8px;font-weight:750;background:#dbf6ec;color:#18765f}.tag.warn{background:#fff2d6;color:#9a690e}.table-scroll{overflow-x:auto}.wide{margin-top:18px}.fine{font-size:12px;line-height:1.7;color:#52657f}.footer{margin-top:25px;color:#60718b;font-size:12px;line-height:1.6}.controls{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
@media(max-width:1020px){.grid{grid-template-columns:repeat(2,1fr)}.section{grid-template-columns:1fr}}@media(max-width:600px){.wrap{padding:12px 12px 40px}header{display:block;padding:23px}h1{font-size:26px}.pill{margin-top:20px}.grid{grid-template-columns:repeat(2,1fr);gap:9px}.metric b{font-size:24px}.card{padding:14px}.nav{margin:19px 0}.nav h2{font-size:18px}}
</style></head><body><div class="wrap"><header><div><div class="eyebrow">Independent business operations portfolio • synthetic case study</div><h1>Service Supply &amp; Quality<br>Operations Simulator</h1><p>Hyderabad • 8 illustrative operating zones • AC Repair, Bathroom Cleaning, Electrician • 28 simulated days • 10-day planning / 18-day policy evaluation</p></div><span class="pill">Not affiliated with Urban Company</span></header>
<div class="nav"><h2>Management scorecard</h2><div class="controls"><label for="scenario">Intervention</label><select id="scenario"></select></div></div>
<div class="grid" id="metrics"></div>
<div class="section"><div class="card"><h3>Performance across five operating policies</h3><p class="sub">Completed booking rate (% of all requests). Recommended option shown in green.</p><div id="bars"></div><div class="callout"><strong>Manager's decision:</strong> Broader geographic coverage improves supply fulfillment, but can increase cross-zone travel. Track service punctuality on <em>all requests</em>, not only completed bookings.</div></div><div class="card"><h3>Service reliability trade-offs</h3><div id="tradeoffs"></div><p class="sub" style="margin-top:18px">All numbers are simulated. On-time is defined by an assumed &le;45-minute travel proxy; it is not an Urban Company SLA.</p></div></div>
<div class="card wide"><div class="nav" style="margin:0 0 15px"><div><h3 style="margin-bottom:3px">Where the operation breaks</h3><div class="sub" style="margin:0">Explore outcomes by locality, service line or scheduling window</div></div><div class="controls"><label for="dimension">Drilldown</label><select id="dimension"><option value="zone">Operating zone</option><option value="category">Service category</option><option value="slot">Service slot</option></select></div></div><div class="table-scroll"><table class="tbl"><thead><tr><th>Segment</th><th class="right">Requests</th><th class="right">Completed</th><th class="right">Fill</th><th class="right">On-time / all</th><th class="right">Complaints</th><th>Status</th></tr></thead><tbody id="segments"></tbody></table></div></div>
<div class="section"><div class="card"><h3>Stress tests • five deterministic seeds</h3><p class="sub">Normal, +15% demand, -10% partner availability. Shows mean booking completion over held-out evaluation windows.</p><div class="table-scroll"><table class="tbl"><thead><tr><th>Condition</th><th>Scenario</th><th class="right">Mean fill</th><th class="right">Observed seed range</th></tr></thead><tbody id="stress"></tbody></table></div></div><div class="card"><h3>Execution blueprint</h3><div class="rowchips"><div class="chip">Train on <strong>10 days</strong></div><div class="chip">Shortlist <strong>12 partners</strong></div><div class="chip">Coach <strong>57 partners</strong></div><div class="chip">Test <strong>18 days</strong></div></div><p class="fine"><b>1.</b> Detect high shortage-pressure category–zone combinations.<br><b>2.</b> Screen &amp; train candidates; activate only verified eligible professionals.<br><b>3.</b> Pool adjacent zones where local service capacity fails.<br><b>4.</b> Track complaints, punctuality, cancellations and partner allocation.<br><b>5.</b> Use a monitored pilot before adopting shift rebalancing.</p><div class="callout">Peak-shift experiment preserves two slots per partner but did not improve the primary customer performance trade-off. Keep it out of the recommended rollout pending validation.</div></div></div>
<p class="footer"><b>Sources and limits:</b> Categories confirmed from Urban Company's Hyderabad public service catalog and partner enablement materials. Zone connectivity, demand generation, staffing, reliability, program costs, cancellation behavior, travel proxy and all KPIs are illustrative and synthetically generated. Program spend is not a claim about Urban Company's cost structure. Complete equations, data and source links are provided in this repository.</p></div>
<script>
const DATA=__DATA__;
const K=DATA.kpis, get=id=>document.getElementById(id),baseline=K[0];
const fmt=(v,dec=1)=>Number(v).toLocaleString('en-IN',{minimumFractionDigits:dec,maximumFractionDigits:dec});
const options=K.map(k=>`<option value="${k.scenario}">${k.scenario}</option>`).join('');
get('scenario').innerHTML=options;get('scenario').value='Quality-Safe Playbook';
function draw(){const chosen=K.find(x=>x.scenario===get('scenario').value),dim=get('dimension').value;
const cards=[['Completed / all requests',fmt(chosen.fill_rate_pct)+'%',fmt(chosen.fill_rate_pct-baseline.fill_rate_pct)+' pp vs baseline',false],['On-time / all requests',fmt(chosen.on_time_fulfillment_pct)+'%',fmt(chosen.on_time_fulfillment_pct-baseline.on_time_fulfillment_pct)+' pp vs baseline',false],['Complaints / completed',fmt(chosen.complaint_pct_of_completed)+'%',fmt(chosen.complaint_pct_of_completed-baseline.complaint_pct_of_completed)+' pp vs baseline',chosen.complaint_pct_of_completed>baseline.complaint_pct_of_completed],['Modeled program spend','₹'+fmt(chosen.model_program_spend_inr,0),fmt(chosen.completed-baseline.completed,0)+' incremental completed',false]];
get('metrics').innerHTML=cards.map(c=>`<div class="card metric"><small>${c[0]}</small><b>${c[1]}</b><div class="delta ${c[3]?'negative':''}">${c[2]}</div></div>`).join('');
get('bars').innerHTML=K.map(k=>`<div class="plotrow"><div class="plotline"><span>${k.scenario}</span><b>${fmt(k.fill_rate_pct)}%</b></div><div class="track"><div class="fill ${k.scenario==='Quality-Safe Playbook'?'recommend':''}" style="width:${k.fill_rate_pct}%"></div></div></div>`).join('');
const p=[['Requests',chosen.requests],['Assigned',chosen.assigned],['Completed',chosen.completed],['Not supplied',chosen.unsupplied_requests],['Partner cancellations',chosen.partner_cancellations],['On-time / completed',fmt(chosen.on_time_pct_of_completed)+'%'],['Slots used / available',fmt(chosen.partner_slot_utilization_pct)+'%'],['New screened partners',chosen.new_partners_selected]];
get('tradeoffs').innerHTML=`<div class="table-scroll"><table class="tbl">${p.map(row=>`<tr><td>${row[0]}</td><td class="right"><b>${row[1]}</b></td></tr>`).join('')}</table></div>`;
const seg=DATA.segments.filter(x=>x.scenario===chosen.scenario&&x.dimension===dim).sort((a,b)=>a.fill_rate_pct-b.fill_rate_pct);
get('segments').innerHTML=seg.map(x=>`<tr><td><b>${x.group}</b></td><td class="right">${x.requests}</td><td class="right">${x.completed}</td><td class="right">${fmt(x.fill_rate_pct)}%</td><td class="right">${fmt(x.on_time_fulfillment_pct)}%</td><td class="right">${fmt(x.complaint_pct)}%</td><td><span class="tag ${x.fill_rate_pct<80?'warn':''}">${x.fill_rate_pct<80?'Investigate':'Healthy in model'}</span></td></tr>`).join('');
const rows=DATA.sensitivity.slice().sort((a,b)=>a.stress_test.localeCompare(b.stress_test)||a.scenario.localeCompare(b.scenario));
get('stress').innerHTML=rows.map(x=>`<tr><td>${x.stress_test}</td><td>${x.scenario}</td><td class="right">${fmt(x.avg_fill_rate_pct)}%</td><td class="right">${fmt(x.min_fill_rate_pct)}%–${fmt(x.max_fill_rate_pct)}%</td></tr>`).join('');}
get('scenario').addEventListener('change',draw);get('dimension').addEventListener('change',draw);draw();
</script></body></html>'''
result=html_page.replace('__DATA__',all_data)
out=ROOT/'dashboard/interactive_dashboard.html';out.write_text(result,encoding='utf-8')
print('Saved',out, 'bytes',out.stat().st_size)
